"""Application logic for the photo-sharing website (Stages 2 and 3).

This module contains no AWS credentials and never constructs AWS clients;
the caller is responsible for supplying an S3 client and a DB-API 2.0
database connection (qmark parameter style, e.g. sqlite3).
"""

from __future__ import annotations

import os
import re
import uuid
from datetime import datetime, timezone

MAX_PHOTO_BYTES = 5 * 1024 * 1024
ALLOWED_CONTENT_TYPES = {"image/jpeg", "image/png"}
_SAFE_CHARS_RE = re.compile(r"[^A-Za-z0-9._-]")


def init_db(conn) -> None:
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key) -> int:
    uploaded_at = datetime.now(timezone.utc).isoformat()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    row_id = cur.lastrowid
    conn.commit()
    return row_id


def search_photos(conn, term):
    cur = conn.cursor()
    cur.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos ORDER BY id ASC"
    )
    rows = cur.fetchall()

    needle = str(term).lower()
    results = []
    for row in rows:
        row_id, title, description, s3_key, uploaded_at = row[0], row[1], row[2], row[3], row[4]
        title_text = title if title is not None else ""
        description_text = description if description is not None else ""
        if needle in title_text.lower() or needle in description_text.lower():
            results.append(
                {
                    "id": row_id,
                    "title": title,
                    "description": description,
                    "s3_key": s3_key,
                    "uploaded_at": uploaded_at,
                }
            )
    return results


def _safe_name(filename: str) -> str:
    base = os.path.basename(filename)
    return _SAFE_CHARS_RE.sub("_", base)


def upload_photo(s3, bucket, filename, data, content_type) -> str:
    if content_type not in ALLOWED_CONTENT_TYPES:
        raise ValueError(f"Unsupported content type: {content_type!r}")
    if len(data) > MAX_PHOTO_BYTES:
        raise ValueError("Photo data exceeds maximum allowed size of 5 MiB")

    safe_name = _safe_name(filename)
    key = f"photos/{uuid.uuid4().hex}/{safe_name}"

    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600) -> str:
    if not (1 <= expires <= 3600):
        raise ValueError("expires must be between 1 and 3600 seconds inclusive")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type) -> int:
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        s3.delete_object(Bucket=bucket, Key=key)
        raise
