import os
import re
import uuid
from datetime import datetime, timezone

ALLOWED_CONTENT_TYPES = frozenset({"image/jpeg", "image/png"})
MAX_UPLOAD_BYTES = 5 * 1024 * 1024
_UNSAFE_CHARS = re.compile(r"[^A-Za-z0-9._-]")


def init_db(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key):
    uploaded_at = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    conn.commit()
    return int(cur.lastrowid)


def search_photos(conn, term):
    if not isinstance(term, str):
        raise ValueError("term must be a string")
    needle = term.casefold()
    cur = conn.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos ORDER BY id ASC"
    )
    results = []
    for row in cur.fetchall():
        photo_id, title, description, s3_key, uploaded_at = row
        title_text = title or ""
        desc_text = description or ""
        if needle in title_text.casefold() or needle in desc_text.casefold():
            results.append(
                {
                    "id": photo_id,
                    "title": title,
                    "description": description,
                    "s3_key": s3_key,
                    "uploaded_at": uploaded_at,
                }
            )
    return results


def _safe_name(filename):
    if not isinstance(filename, str):
        raise ValueError("filename must be a string")
    base = filename.replace("\\", "/").rsplit("/", 1)[-1]
    safe = _UNSAFE_CHARS.sub("_", base)
    if safe in ("", ".", ".."):
        raise ValueError("filename does not produce a usable name")
    return safe


def upload_photo(s3, bucket, filename, data, content_type):
    if content_type not in ALLOWED_CONTENT_TYPES:
        raise ValueError("unsupported content type: %r" % (content_type,))
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")
    if len(data) > MAX_UPLOAD_BYTES:
        raise ValueError("file exceeds 5 MiB limit")
    safe = _safe_name(filename)
    key = "photos/%s/%s" % (uuid.uuid4().hex, safe)
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600):
    if isinstance(expires, bool) or not isinstance(expires, int):
        raise ValueError("expires must be an integer")
    if not 1 <= expires <= 3600:
        raise ValueError("expires must be between 1 and 3600 seconds")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type):
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        try:
            s3.delete_object(Bucket=bucket, Key=key)
        except Exception:
            pass
        raise
